import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { chromium } from '/Users/jamie/development/exposed.member-money-sources/frontend/node_modules/playwright-core/index.mjs';
const worktree = '/Users/jamie/development/exposed.member-money-sources/frontend';
const fixture = await readFile('/tmp/exposed-money-sources/member-178-api.json', 'utf8');
const backend = createServer((req, res) => {
  if (req.url === '/members/178') res.writeHead(200, {'content-type': 'application/json'}).end(fixture);
  else res.writeHead(404).end();
});
backend.listen(0, '127.0.0.1');
await once(backend, 'listening');
const app = spawn(process.execPath, ['build'], {cwd: worktree, env: {...process.env, HOST: '127.0.0.1', PORT: '4189', PUBLIC_POSTHOG_PROJECT_TOKEN: '', PUBLIC_POSTHOG_HOST: '', EXPOSED_API_ORIGIN: `http://127.0.0.1:${backend.address().port}`}, stdio: 'pipe'});
let browser;
try {
  for(let n = 0; n < 100; n++) {
    try { if ((await fetch('http://127.0.0.1:4189')).ok) break; } catch {}
    await new Promise(r => setTimeout(r, 100));
  }
  browser = await chromium.launch({headless: true});
  const page = await browser.newPage({viewport: {width: 1440, height: 1000}, deviceScaleFactor: 1});
  await page.goto('http://127.0.0.1:4189/members/178');
  await page.getByRole('heading', {name: 'Declared amounts by source', exact: true}).waitFor();
  const table = page.getByRole('table', {name: 'Sources ranked by known declared GBP amounts'});
  if (await table.getByRole('row').count() !== 6) throw new Error('Expected five actual recorded sources.');
  await page.screenshot({path: '/tmp/exposed-money-sources/john-mcdonnell-desktop.png', fullPage: true});
  await page.setViewportSize({width: 390, height: 844});
  if (!await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)) throw new Error('Mobile page overflows.');
  await page.screenshot({path: '/tmp/exposed-money-sources/john-mcdonnell-mobile.png', fullPage: true});
  console.log('Captured real local API response replay in the branch production build. Five sources rendered. Mobile has no page overflow.');
} finally {
  await browser?.close();
  app.kill('SIGTERM');
  await once(app, 'exit');
  backend.closeAllConnections();
  await new Promise(r => backend.close(r));
}

